import{_ as i}from"./chunks/Audio.COine8Wh.js";import{_ as r}from"./chunks/Tags.BJ536pW3.js";import{c as n,o as s,j as a,G as t,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Wounded Knee Massacre Memorial and Sacred Site Act","description":"","frontmatter":{"legisId":"2025-12-19-wounded-knee-massacre-memorial-and-sacred-site-act","title":"Wounded Knee Massacre Memorial and Sacred Site Act","displayTitle":"Wounded Knee Massacre Memorial and Sacred Site Act","lawNumber":"119-61","billNumber":"H.R. 165","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ61.xml","publishDate":"2025-12-19T00:00:00-05:00","industries":["government-operations"],"agencies":["Department of the Interior"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Wounded Knee Massacre Memorial and Sacred Site Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-19-wounded-knee-massacre-memorial-and-sacred-site-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Wounded Knee Massacre Memorial and Sacred Site Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-19-wounded-knee-massacre-memorial-and-sacred-site-act\\",\\"datePublished\\":\\"2025-12-19T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-19-wounded-knee-massacre-memorial-and-sacred-site-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-12-19-wounded-knee-massacre-memorial-and-sacred-site-act.md","filePath":"congress-bills/2025-12-19-wounded-knee-massacre-memorial-and-sacred-site-act.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2025-12-19-wounded-knee-massacre-memorial-and-sacred-site-act.md"},b=Object.assign(d,{setup(c){return(m,e)=>(s(),n("div",null,[e[0]||(e[0]=a("h1",{id:"wounded-knee-massacre-memorial-and-sacred-site-act",tabindex:"-1"},[l("Wounded Knee Massacre Memorial and Sacred Site Act "),a("a",{class:"header-anchor",href:"#wounded-knee-massacre-memorial-and-sacred-site-act","aria-label":'Permalink to "Wounded Knee Massacre Memorial and Sacred Site Act"'},"​")],-1)),t(i),t(r,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Friday, December 19, 2025. Public Law 119-61, H.R. 165.</p><p><strong>Headline:</strong> The law protects about 40 acres at the Wounded Knee Massacre site under continued tribal ownership.</p><p><strong>Why it matters:</strong> The site will become part of the Pine Ridge Indian Reservation, be shielded from state and local taxes, and generally be governed as Indian country.</p><p><strong>What the law does:</strong></p><ul><li>Requires the Interior Secretary to finalize documentation, minor land-description corrections, and applicable utility and service rights within 365 days.</li><li>Keeps the land jointly owned by the Oglala Sioux Tribe and Cheyenne River Sioux Tribe under restricted fee status.</li><li>Places the land under the Oglala Sioux Tribe’s civil and criminal jurisdiction.</li><li>Bars transfers without approval from Congress and both Tribes.</li><li>Limits use to purposes allowed by the Tribes’ October 21, 2022 covenant and prohibits gaming.</li><li>Preserves existing easements, rights-of-way, restrictions, encumbrances, and utility agreements.</li></ul><p><strong>Who it affects:</strong></p><ul><li>The Oglala Sioux Tribe and Cheyenne River Sioux Tribe.</li><li>State and local governments that otherwise might tax or exercise authority over the land.</li><li>People and entities holding existing land-access, utility, or service rights.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Visitors and community members will see the site preserved and used under the Tribes’ covenant.</li><li>State and local taxpayers will not collect property taxes from the covered land.</li></ul><p><strong>Context:</strong> The protected property includes about 40 acres of land, minerals, improvements, structures, and personal property at the Wounded Knee Massacre site.</p><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="wounded-knee-massacre-memorial-and-sacred-site-act-1" tabindex="-1">Wounded Knee Massacre Memorial and Sacred Site Act <a class="header-anchor" href="#wounded-knee-massacre-memorial-and-sacred-site-act-1" aria-label="Permalink to &quot;Wounded Knee Massacre Memorial and Sacred Site Act&quot;">​</a></h3><p>This law requires the Secretary of the Interior to complete the steps needed for the Oglala Sioux Tribe and Cheyenne River Sioux Tribe to hold about 40 acres at the Wounded Knee Massacre site in restricted fee status. The Tribes will continue to own the land, which will be protected from state and local taxation and generally governed as Indian country. The land must be used according to the Tribes’ 2022 covenant and may not be used for gaming.</p><p><strong>Key takeaways:</strong></p><ul><li>The law covers about 40 acres at the Wounded Knee Massacre site on the Pine Ridge Indian Reservation, including the land, minerals, improvements, structures, and personal property located there.</li><li>The Secretary of the Interior must complete the necessary documentation, minor survey or legal-description corrections, and assignment of applicable utility and service rights within 365 days after enactment.</li><li>The land will remain owned by both Tribes, become part of the Pine Ridge Indian Reservation, and fall under the Oglala Sioux Tribe’s civil and criminal jurisdiction.</li><li>The land cannot be transferred without the consent of Congress and both Tribes, and state and local governments cannot tax it.</li><li>The Tribes may use the land without prior Interior Department review or approval, but only for purposes allowed by their October 21, 2022 covenant.</li><li>Existing easements, rights-of-way, restrictions, encumbrances, and utility agreements remain in effect, and gaming is prohibited on the land.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ61.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ61.xml</a></p>',16))]))}});export{g as __pageData,b as default};
